'use strict';
/* 바이브 서버: 외부 패키지 없이 Node.js(18 이상)만으로 동작합니다.  실행:  node vibe.js */
const http = require('http'), crypto = require('crypto'), fs = require('fs'), path = require('path');
const PORT = +process.env.PORT || 3000;
const DATA_DIR = process.env.VIBE_DATA || path.join(process.cwd(), 'vibe-data');
const MEDIA_DIR = path.join(DATA_DIR, 'media');
fs.mkdirSync(MEDIA_DIR, { recursive: true });
const DB_FILE = path.join(DATA_DIR, 'data.json');

let db = { users: {}, rooms: {}, msgs: {}, sessions: {} };
try { db = Object.assign(db, JSON.parse(fs.readFileSync(DB_FILE, 'utf8'))); } catch (e) {}
let saveT = null;
function writeNow() {
  const tmp = DB_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(db));
  fs.renameSync(tmp, DB_FILE);
}
function save() {
  if (saveT) return;
  saveT = setTimeout(() => { saveT = null; try { writeNow(); } catch (e) { console.error('저장 실패', e.message); } }, 400);
}
function flushAndExit() { try { if (saveT) clearTimeout(saveT); writeNow(); } catch (e) {} process.exit(0); }
process.on('SIGINT', flushAndExit);
process.on('SIGTERM', flushAndExit);
process.on('uncaughtException', e => console.error('오류:', e));

const rnd = n => crypto.randomBytes(n).toString('hex');
const now = () => Date.now();
const clean = (s, max) => String(s == null ? '' : s).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
function hashPw(pw, salt) { salt = salt || rnd(16); return salt + ':' + crypto.scryptSync(String(pw), salt, 32).toString('hex'); }
function checkPw(pw, stored) {
  if (!stored) return false;
  const [salt, h] = stored.split(':');
  const a = Buffer.from(h, 'hex'), b = crypto.scryptSync(String(pw), salt, 32);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

/* ICE(통화 연결) 서버. 다른 통신망끼리 통화가 안 되면 TURN 서버를 환경변수로 지정하세요. */
let ICE = [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun1.l.google.com:19302' }];
try { if (process.env.ICE_SERVERS) ICE = JSON.parse(process.env.ICE_SERVERS); } catch (e) { console.error('ICE_SERVERS 형식 오류'); }
if (!process.env.ICE_SERVERS && !process.env.TURN_URL) ICE.push({ urls: ['turn:openrelay.metered.ca:80', 'turn:openrelay.metered.ca:443', 'turn:openrelay.metered.ca:443?transport=tcp'], username: 'openrelayproject', credential: 'openrelayproject' });
if (process.env.TURN_URL) ICE.push({ urls: process.env.TURN_URL.split(','), username: process.env.TURN_USER || '', credential: process.env.TURN_PASS || '' });

/* ---------- 최소 WebSocket 구현 (RFC 6455) ---------- */
class Conn {
  constructor(sock) {
    this.sock = sock; this.buf = Buffer.alloc(0); this.user = null; this.token = null;
    this.alive = true; this.frag = []; this.fop = 1; this.ip = sock.remoteAddress;
    sock.on('data', d => { this.buf = Buffer.concat([this.buf, d]); try { while (this.parse()) {} } catch (e) { sock.destroy(); } });
    sock.on('close', () => onClose(this));
    sock.on('error', () => {});
  }
  parse() {
    const b = this.buf;
    if (b.length < 2) return false;
    const fin = !!(b[0] & 0x80), op = b[0] & 0x0f, masked = !!(b[1] & 0x80);
    let len = b[1] & 0x7f, off = 2;
    if (len === 126) { if (b.length < 4) return false; len = b.readUInt16BE(2); off = 4; }
    else if (len === 127) { if (b.length < 10) return false; len = Number(b.readBigUInt64BE(2)); off = 10; }
    if (len > 8 * 1024 * 1024) { this.sock.destroy(); return false; }
    const need = off + (masked ? 4 : 0) + len;
    if (b.length < need) return false;
    let payload = b.subarray(off + (masked ? 4 : 0), need);
    if (masked) { const m = b.subarray(off, off + 4); payload = Buffer.from(payload); for (let i = 0; i < payload.length; i++) payload[i] ^= m[i & 3]; }
    this.buf = b.subarray(need);
    if (op === 8) { this.sock.end(); return false; }
    if (op === 9) { this.sendRaw(10, payload); return true; }
    if (op === 10) { this.alive = true; return true; }
    if (op === 0 || op === 1 || op === 2) {
      if (op !== 0) { this.fop = op; this.frag = []; }
      this.frag.push(payload);
      if (fin) { const full = Buffer.concat(this.frag); this.frag = []; if (this.fop === 1) onMessage(this, full.toString('utf8')); }
    }
    return true;
  }
  sendRaw(op, payload) {
    const len = payload.length; let h;
    if (len < 126) h = Buffer.from([0x80 | op, len]);
    else if (len < 65536) { h = Buffer.alloc(4); h[0] = 0x80 | op; h[1] = 126; h.writeUInt16BE(len, 2); }
    else { h = Buffer.alloc(10); h[0] = 0x80 | op; h[1] = 127; h.writeBigUInt64BE(BigInt(len), 2); }
    try { this.sock.write(Buffer.concat([h, payload])); } catch (e) {}
  }
  send(obj) { this.sendRaw(1, Buffer.from(JSON.stringify(obj))); }
}
setInterval(() => {
  for (const set of conns.values()) for (const c of set) {
    if (!c.alive) { c.sock.destroy(); continue; }
    c.alive = false; c.sendRaw(9, Buffer.alloc(0));
  }
}, 30000).unref();

/* ---------- 접속 관리 ---------- */
const conns = new Map(); // userId -> Set<Conn>
const send = (uid, obj) => { const s = conns.get(uid); if (s) for (const c of s) c.send(obj); };
const online = uid => !!(conns.get(uid) && conns.get(uid).size);


/* ---------- 프로필 / 방 정보 조립 ---------- */
const tagList = t => (Array.isArray(t) ? t : String(t || '').split(/[,#\s]+/)).map(x => clean(x, 12)).filter(Boolean).slice(0, 5);
const voices = new Map(); // 바이브챗 음성채팅: rid -> Set(uid)
const VOICE_MAX = 8;
const EMPTY_PROF = { name: '알 수 없음', status: '', tags: [], photo: '', bg: '' };
const kstDay = () => new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10);
function migrate(u) {
  if (!u.profile) {
    const ps = u.profiles || [{ name: u.id }];
    u.profile = Object.assign({ name: u.id, status: '', tags: [], photo: '', bg: '', deco: '' }, ps[u.def || 0] || ps[0]);
    u.vps = ps.slice(0, 3).map(p => Object.assign({ status: '', tags: [], photo: '', bg: '', deco: '' }, p));
    delete u.profiles; delete u.def; delete u.viewMap;
  }
  u.vps = u.vps || [Object.assign({}, u.profile)]; u.vps.forEach(p => { if (!p.pid) p.pid = rnd(4); }); u.vpost = u.vpost || {};
  u.friends = u.friends || []; u.reqIn = u.reqIn || []; u.reqOut = u.reqOut || []; u.blocked = u.blocked || [];
}
Object.values(db.users).forEach(migrate); db.reports = db.reports || [];
const firstUser = () => Object.values(db.users).sort((a, b) => (a.created || 0) - (b.created || 0))[0];
const ADMINS = String(process.env.ADMIN_IDS || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const isAdmin = uid => ADMINS.length ? ADMINS.includes(uid) : (firstUser() && firstUser().id === uid);
function publicProf(u, idx) {
  const p = idx == null ? u.profile : (u.vps[idx] || u.vps[0] || u.profile);
  return { name: p.name, status: p.status || '', tags: p.tags || [], photo: p.photo || '', bg: p.bg || '', pid: p.pid || '' };
}
function memberProf(room, uid) {
  const u = db.users[uid]; if (!u) return EMPTY_PROF;
  return publicProf(u, room.type === 'vc' ? ((room.members[uid] && room.members[uid].pidx) || 0) : null);
}
function unreadOf(room, uid) {
  const m = room.members[uid]; if (!m) return 0;
  let n = 0; const list = db.msgs[room.id] || [];
  for (let i = list.length - 1; i >= 0 && list[i].seq > (m.readSeq || 0); i--) if (list[i].from !== uid && list[i].t !== 'sys') n++;
  return n;
}
function roomFor(room, viewer) {
  const members = {};
  for (const uid in room.members) members[uid] = Object.assign({}, memberProf(room, uid), { readSeq: room.members[uid].readSeq || 0 });
  for (const g of (room.guests || [])) members[g.id] = { name: g.name, status: '', tags: [], photo: '', bg: '', pid: '', readSeq: 1e12, guest: true, joined: g.ts };
  return {
    id: room.id, type: room.type, name: room.name, desc: room.desc || '', photo: room.photo || '', tags: room.tags || [], bot: room.type === 'vc' && room.bot ? room.bot : null,
    onlyStaff: !!room.onlyStaff, voice: voices.has(room.id) ? [...voices.get(room.id)] : null,
    cap: room.cap || 0, hasPw: !!room.pw,
    owner: room.owner || '', vices: room.vices || [], cos: room.cos || [], notice: room.notice || null, seq: room.seq || 0,
    last: room.last || null, ts: room.ts, unread: unreadOf(room, viewer), members
  };
}
const pubUser = id => { const f = db.users[id]; return f ? Object.assign({ id }, publicProf(f)) : { id, name: id, status: '', tags: [], photo: '', bg: '' }; };
function syncFor(uid) {
  const u = db.users[uid];
  const friends = u.friends.map(fid => db.users[fid] ? Object.assign({ online: online(fid) }, pubUser(fid)) : null).filter(Boolean);
  const rooms = Object.values(db.rooms).filter(r => r.members[uid]).map(r => roomFor(r, uid));
  return { me: { id: u.id, profile: u.profile, vps: u.vps, blocked: u.blocked.map(pubUser), admin: !!isAdmin(uid) },
    friends, reqIn: u.reqIn.map(pubUser), reqOut: u.reqOut.map(pubUser), rooms, ice: ICE };
}
function pushSync(uid) { if (online(uid)) send(uid, Object.assign({ ev: 'sync' }, syncFor(uid))); }
function affected(uid) {
  const s = new Set([uid]); const u = db.users[uid];
  if (u) [].concat(u.friends, u.reqIn, u.reqOut).forEach(f => s.add(f));
  for (const o of Object.values(db.users)) if (o.friends.includes(uid) || o.reqIn.includes(uid) || o.reqOut.includes(uid)) s.add(o.id);
  for (const r of Object.values(db.rooms)) if (r.members[uid]) for (const m in r.members) s.add(m);
  return s;
}
function pushRoomSync(room, extra) { const s = new Set(Object.keys(room.members)); (extra || []).forEach(x => s.add(x)); s.forEach(pushSync); }

/* ---------- 메시지 ---------- */
function cm(m, viewer) {
  if (m.t !== 'poll' || !m.poll) return m;
  const p = m.poll;
  return Object.assign({}, m, { poll: {
    q: p.q, multi: p.multi, anon: p.anon, closed: p.closed, by: p.by,
    opts: p.opts.map(o => ({ id: o.id, text: o.text, n: o.v.length, voters: p.anon ? undefined : o.v })),
    mine: p.opts.filter(o => o.v.includes(viewer)).map(o => o.id)
  } });
}
function lastText(m) {
  if (m.del) return '삭제된 메시지입니다';
  if (m.t === 'img') return '사진';
  if (m.t === 'sticker') return '스티커';
  if (m.t === 'bot') return '바이브챗봇: ' + m.text;
  if (m.t === 'poll') return '투표: ' + m.text;
  return m.text;
}
function addMsg(room, m) {
  room.seq = (room.seq || 0) + 1;
  m.id = rnd(6); m.seq = room.seq; m.ts = now();
  const list = (db.msgs[room.id] = db.msgs[room.id] || []);
  list.push(m); if (list.length > 3000) list.splice(0, 500);
  room.ts = m.ts; room.last = { t: m.t, text: String(lastText(m)).slice(0, 60), ts: m.ts, from: m.from || '' };
  if (m.from && room.members[m.from]) room.members[m.from].readSeq = room.seq;
  for (const uid in room.members) send(uid, { ev: 'msg', rid: room.id, m: cm(m, uid), last: room.last, seq: room.seq, ts: room.ts });
  save(); return m;
}
const sysMsg = (room, text) => addMsg(room, { from: '', t: 'sys', text, img: '' });
function updMsg(room, m) { for (const uid in room.members) send(uid, { ev: 'msgupd', rid: room.id, m: cm(m, uid), last: room.last }); save(); }
const nameIn = (room, uid) => memberProf(room, uid).name;

/* ---------- 요청 처리 ---------- */
class Fail extends Error {}
const need = (c, msg) => { if (!c) throw new Fail(msg); };
const U = c => { need(c.user, '로그인이 필요해요'); return db.users[c.user]; };
const R = (rid, uid) => { const r = db.rooms[rid]; need(r && r.members[uid], '채팅방을 찾을 수 없어요'); return r; };
const isOwner = (r, uid) => r.owner === uid;
const isCo = (r, uid) => (r.cos || []).includes(uid);
const isStaff = (r, uid) => r.owner === uid || isCo(r, uid) || (r.vices || []).includes(uid);
const okMedia = u => (typeof u === 'string' && /^\/m\/[a-f0-9]{24}\.(jpg|png|webp|gif)$/.test(u)) ? u : '';
const dmId = (a, b) => 'dm_' + [a, b].sort().join('_');
const loginTries = new Map();

function attach(c, uid, token) {
  c.user = uid; c.token = token;
  let s = conns.get(uid); if (!s) conns.set(uid, s = new Set());
  const first = s.size === 0; s.add(c);
  if (first) for (const f of db.users[uid].friends) send(f, { ev: 'pres', id: uid, online: true });
}
function onClose(c) {
  const uid = c.user; if (!uid) return;
  const s = conns.get(uid); if (!s) return;
  s.delete(c);
  if (!s.size) {
    conns.delete(uid);
    for (const f of db.users[uid].friends) send(f, { ev: 'pres', id: uid, online: false });
    for (const [rid, set] of [...voices]) if (set.has(uid) && db.rooms[rid]) voiceLeave(db.rooms[rid], uid);
    for (const call of [...calls.values()]) if (call.from === uid || call.to === uid) endCall(call.id, call.state === 'ringing' ? (call.from === uid ? 'canceled' : 'declined') : 'ended');
  }
}

const H = {};
H.signup = (c, r) => {
  const id = String(r.id || '').trim().toLowerCase();
  need(/^[a-z0-9_]{4,16}$/.test(id), '아이디는 영문 소문자·숫자·_ 4~16자로 입력해 주세요');
  need(String(r.pw || '').length >= 4 && String(r.pw).length <= 64, '비밀번호는 4자 이상이어야 해요');
  const nick = clean(r.nick, 20); need(nick, '닉네임은 1~20자로 입력해 주세요');
  need(!db.users[id], '이미 사용 중인 아이디예요');
  db.users[id] = { id, pw: hashPw(r.pw), created: now(), profile: { name: nick, status: '', tags: [], photo: '', bg: '' }, vps: [{ name: nick, status: '', tags: [], photo: '', bg: '', pid: rnd(4) }], vpost: {}, friends: [], reqIn: [], reqOut: [], blocked: [] };
  const token = rnd(24); db.sessions[token] = id; save(); attach(c, id, token);
  return Object.assign({ token }, syncFor(id));
};
H.login = (c, r) => {
  const ip = c.ip || '', t = now(); const arr = (loginTries.get(ip) || []).filter(x => t - x < 60000);
  need(arr.length < 12, '로그인 시도가 너무 많아요. 잠시 후 다시 해 주세요'); arr.push(t); loginTries.set(ip, arr);
  const id = String(r.id || '').trim().toLowerCase(); const u = db.users[id];
  need(u && checkPw(r.pw || '', u.pw), '아이디 또는 비밀번호가 맞지 않아요');
  const token = rnd(24); db.sessions[token] = id; save(); attach(c, id, token);
  return Object.assign({ token }, syncFor(id));
};
H.resume = (c, r) => {
  const id = db.sessions[String(r.token || '')]; need(id && db.users[id], '다시 로그인해 주세요');
  attach(c, id, r.token); return syncFor(id);
};
H.logout = (c) => { if (c.token) delete db.sessions[c.token]; save(); onClose(c); c.user = null; c.token = null; return {}; };
H.ping = () => ({});

H.upload = (c, r) => {
  U(c);
  const m = /^data:image\/(jpeg|png|webp|gif);base64,([A-Za-z0-9+\/=]+)$/.exec(String(r.data || ''));
  need(m, '이미지 형식이 올바르지 않아요');
  const buf = Buffer.from(m[2], 'base64'); need(buf.length > 0 && buf.length <= 3 * 1024 * 1024, '이미지가 너무 커요');
  const id = rnd(12) + '.' + (m[1] === 'jpeg' ? 'jpg' : m[1]);
  fs.writeFileSync(path.join(MEDIA_DIR, id), buf);
  return { url: '/m/' + id };
};

const cleanProf = (p, u) => {
  const name = clean(p && p.name, 20); need(name, '프로필 이름을 입력해 주세요');
  const tags = (Array.isArray(p.tags) ? p.tags : []).map(t => clean(t, 20)).filter(Boolean).slice(0, 10);
  const pid = (u.vps || []).some(x => x.pid === p.pid) ? p.pid : rnd(4);
  return { name, status: clean(p.status, 120), tags, photo: okMedia(p.photo), bg: okMedia(p.bg), pid };
};
H.profile_save = (c, r) => {
  const u = U(c);
  if (r.profile) u.profile = cleanProf(r.profile, u);
  if (r.vps) {
    need(Array.isArray(r.vps) && r.vps.length >= 1 && r.vps.length <= 3, '바이브챗 프로필은 1~3개까지 만들 수 있어요');
    const ps = r.vps.map(p => cleanProf(p, u));
    const rem = Number.isInteger(r.removed) ? r.removed : -1;
    const shift = v => (rem < 0 || v == null) ? v : (v === rem ? 0 : (v > rem ? v - 1 : v));
    for (const room of Object.values(db.rooms)) if (room.type === 'vc' && room.members[u.id]) {
      const nv = shift(room.members[u.id].pidx || 0); room.members[u.id].pidx = nv >= ps.length ? 0 : nv;
    }
    u.vps = ps;
  }
  save(); for (const x of affected(u.id)) pushSync(x);
  return {};
};
const isBlocked = (a, b) => (db.users[a] && db.users[a].blocked.includes(b)) || (db.users[b] && db.users[b].blocked.includes(a));
const drop = (arr, x) => { const i = arr.indexOf(x); if (i >= 0) arr.splice(i, 1); };
function makeFriends(a, b) {
  for (const [x, y] of [[a, b], [b, a]]) { const u = db.users[x]; drop(u.reqIn, y); drop(u.reqOut, y); if (!u.friends.includes(y)) u.friends.push(y); }
}
H.friend_req = (c, r) => {
  const u = U(c); const id = String(r.id || '').trim().toLowerCase();
  need(id, '친구 아이디를 입력해 주세요'); need(id !== u.id, '나 자신에게는 요청할 수 없어요');
  const f = db.users[id]; need(f, '해당 아이디의 사용자를 찾을 수 없어요'); need(!u.friends.includes(id), '이미 친구예요');
  need(!isBlocked(u.id, id), '친구 요청을 보낼 수 없어요'); need(!u.reqOut.includes(id), '이미 요청을 보냈어요');
  if (u.reqIn.includes(id)) { makeFriends(u.id, id); save(); pushSync(u.id); pushSync(id); return { name: publicProf(f).name, accepted: true }; }
  need(u.reqOut.length < 50, '보낸 요청이 너무 많아요');
  u.reqOut.push(id); f.reqIn.push(u.id); save(); pushSync(u.id); pushSync(id);
  send(id, { ev: 'freq', from: pubUser(u.id) });
  return { name: publicProf(f).name };
};
H.req_accept = (c, r) => { const u = U(c); need(u.reqIn.includes(r.id) && db.users[r.id], '받은 요청이 없어요'); makeFriends(u.id, r.id); save(); pushSync(u.id); pushSync(r.id); return {}; };
H.req_decline = (c, r) => { const u = U(c); const f = db.users[r.id]; drop(u.reqIn, r.id); if (f) drop(f.reqOut, u.id); save(); pushSync(u.id); pushSync(r.id); return {}; };
H.req_cancel = (c, r) => { const u = U(c); const f = db.users[r.id]; drop(u.reqOut, r.id); if (f) drop(f.reqIn, u.id); save(); pushSync(u.id); pushSync(r.id); return {}; };
H.friend_del = (c, r) => { const u = U(c); const f = db.users[r.id]; drop(u.friends, r.id); if (f) drop(f.friends, u.id); save(); pushSync(u.id); pushSync(r.id); return {}; };
H.block = (c, r) => {
  const u = U(c); const id = String(r.id || ''); need(db.users[id] && id !== u.id, '차단할 수 없는 대상이에요');
  if (!u.blocked.includes(id)) u.blocked.push(id);
  const f = db.users[id]; drop(u.friends, id); drop(f.friends, u.id); drop(u.reqIn, id); drop(u.reqOut, id); drop(f.reqIn, u.id); drop(f.reqOut, u.id);
  save(); pushSync(u.id); pushSync(id); return {};
};
H.unblock = (c, r) => { const u = U(c); drop(u.blocked, r.id); save(); pushSync(u.id); return {}; };

/* ---------- 바이브챗 프로필 포스트 ---------- */
const postsOf = (u, pid) => (u.vpost[pid] = u.vpost[pid] || []);
H.post_add = (c, r) => {
  const u = U(c); need(u.vps.some(p => p.pid === r.pid), '프로필을 찾을 수 없어요');
  const text = clean(r.text, 200), img = okMedia(r.img); need(text || img, '포스트 내용을 입력해 주세요');
  const list = postsOf(u, r.pid); need(list.length < 100, '포스트는 프로필마다 100개까지예요');
  list.unshift({ id: rnd(5), text, img, ts: now(), likes: [] }); save(); return {};
};
H.post_del = (c, r) => { const u = U(c); const list = postsOf(u, r.pid); const i = list.findIndex(x => x.id === r.id); need(i >= 0, '포스트를 찾을 수 없어요'); list.splice(i, 1); save(); return {}; };
const postView = (list, me) => list.map(x => ({ id: x.id, text: x.text, img: x.img, ts: x.ts, n: x.likes.length, liked: x.likes.includes(me) }));
