const GW = ['피치','하늘','도토리','밤하늘','라떼','모카','구름','솜사탕','별빛','민트','초코','새벽','노을','까치','다람','보리','토마토','레몬','달빛','푸딩','제리','코코','마루','나비','바다','단풍','소라','체리','우유','호랑','해바라기','딸기','쿠키','사이다','오렌지','포도','은하','호두','뭉치','하루','유나','지우','서준','민재','다온','나린','이든','소미','시온','가을'];
H.room_guests = (c, r) => {
  const u = U(c); const room = R(r.rid, u.id); need(room.type !== 'dm' && isOwner(room, u.id), '방장만 쓸 수 있어요');
  room.guests = room.guests || []; const n = Math.max(1, Math.min(50, parseInt(r.n, 10) || 0)); need(n > 0, '인원 수를 입력해 주세요');
  if (r.dir === 'down') {
    const k = Math.min(n, room.guests.length); need(k > 0, '게스트가 없어요'); room.guests.splice(room.guests.length - k, k);
    sysMsg(room, '게스트 ' + k + '명이 퇴장했습니다'); pushRoomSync(room); if (room.type === 'vc') broadcastVc(); return { n: k };
  }
  need(room.guests.length + n <= 300, '게스트는 최대 300명까지예요');
  const used = new Set(room.guests.map(g => g.name).concat(Object.keys(room.members).map(x => nameIn(room, x))));
  for (let i = 0; i < n; i++) {
    let nm, tries = 0;
    do { nm = GW[Math.floor(Math.random() * GW.length)]; if (Math.random() < 0.2) nm += ' Bolt' + (2 + Math.floor(Math.random() * 3)); else if (tries > 5) nm += Math.floor(Math.random() * 90 + 10); tries++; } while (used.has(nm) && tries < 40);
    used.add(nm); room.guests.push({ id: 'g_' + rnd(6), name: nm, ts: Date.now() });
  }
  sysMsg(room, '게스트 ' + n + '명이 입장했습니다'); pushRoomSync(room); if (room.type === 'vc') broadcastVc(); return { n };
};
H.room_only = (c, r) => {
  const u = U(c); const room = R(r.rid, u.id); need(room.type !== 'dm' && isStaff(room, u.id), '방장과 부방장만 바꿀 수 있어요');
  room.onlyStaff = !!r.on; sysMsg(room, room.onlyStaff ? '지금부터 방장과 부방장만 말할 수 있어요' : '이제 모두 말할 수 있어요'); pushRoomSync(room); return {};
};

/* ---------- 음성채팅 (바이브챗) ---------- */
function voiceLeave(room, uid, quiet) {
  const set = voices.get(room.id); if (!set || !set.has(uid)) return;
  set.delete(uid);
  if (!set.size) { voices.delete(room.id); if (!quiet) sysMsg(room, '음성채팅이 종료되었습니다'); } else if (!quiet) sysMsg(room, nameIn(room, uid) + '님이 음성채팅에서 나갔습니다');
  for (const x of set) send(x, { ev: 'vleft', rid: room.id, uid });
  pushRoomSync(room, [uid]);
}
H.voice_join = (c, r) => {
  const u = U(c); const room = R(r.rid, u.id); need(room.type === 'vc', '바이브챗에서만 음성채팅을 쓸 수 있어요');
  let set = voices.get(room.id); const fresh = !set; if (!set) voices.set(room.id, set = new Set());
  if (set.has(u.id)) return { peers: [...set].filter(x => x !== u.id) };
  need(set.size < VOICE_MAX, '음성채팅은 최대 ' + VOICE_MAX + '명까지예요');
  const peers = [...set]; set.add(u.id);
  sysMsg(room, fresh ? nameIn(room, u.id) + '님이 음성채팅을 시작했어요. 참여하려면 >음성채팅참여' : nameIn(room, u.id) + '님이 음성채팅에 참여했습니다');
  pushRoomSync(room); return { peers };
};
H.voice_open = H.voice_join;
