  need(m.t === 'poll' && m.poll && !m.poll.closed, '종료된 투표예요');
  const opt = m.poll.opts.find(o => o.id === (r.opt | 0)); need(opt, '항목을 찾을 수 없어요');
  const has = opt.v.includes(u.id);
